<?php require 'config.php';role_required(['admin','teacher']);$id=(int)($_GET['circle']??0);$s=$pdo->prepare('SELECT e.id,u.name FROM enrollments e JOIN users u ON u.id=e.user_id WHERE e.circle_id=? AND e.status="active"');$s->execute([$id]);$students=$s->fetchAll();$date=$_POST['date']??date('Y-m-d');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($students as $st){$status=isset($_POST['present'][$st['id']])?'present':'absent';$q=$pdo->prepare('INSERT INTO attendance(enrollment_id,date,status,recorded_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),recorded_by=VALUES(recorded_by)');$q->execute([$st['id'],$date,$status,user()['id']]);}$saved=true;}header_html('تسجيل الحضور');if(!empty($saved))echo '<div class="alert success">تم حفظ الحضور.</div>';?><form method="post" class="card"><label>التاريخ<input type="date" name="date" value="<?=e($date)?>"></label><table><tr><th>الطالب</th><th>حاضر</th></tr><?php foreach($students as $st): ?><tr><td><?=e($st['name'])?></td><td><input type="checkbox" name="present[<?=$st['id']?>]" value="1"></td></tr><?php endforeach; ?></table><input type="hidden" name="csrf" value="<?=csrf()?>"><button>حفظ</button></form><?php footer_html(); ?>